mapper.select:
select t3.* ,
       t2.id relation_id,t2.team_id relation_team_id,t2.player_id relation_player_id,
       t2.jersey_number relation_jersey_number,t2.position relation_position
from   third_sport_team t1,third_team_player_relation t2,third_sport_player t3
where  t1.id = #{team.id}

    and   t1.data_source_code = #{team.dataSourceCode}


    and   t1.sport_id = #{team.sportId}

and    t1.id = t2.team_id
and    t2.player_id = t3.id
